CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('production_manager','machine_operator')), plant_owner_id uuid NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
INSERT INTO public.user_roles(user_id,role,plant_owner_id) SELECT id,'production_manager',id FROM auth.users;
CREATE TABLE public.machine_assignments (user_id uuid NOT NULL, machine_id uuid NOT NULL REFERENCES public.machines(id), PRIMARY KEY(user_id,machine_id));
GRANT SELECT ON public.machine_assignments TO authenticated; GRANT ALL ON public.machine_assignments TO service_role;
ALTER TABLE public.machine_assignments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.operator_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), email text NOT NULL, token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, machine_ids uuid[] NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', accepted_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.operator_invites TO authenticated; GRANT ALL ON public.operator_invites TO service_role;
ALTER TABLE public.operator_invites ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_plant_manager(p_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='production_manager' AND plant_owner_id=p_owner) $$;
CREATE FUNCTION public.can_read_machine(p_id uuid,p_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_plant_manager(p_owner) OR EXISTS(SELECT 1 FROM public.user_roles r JOIN public.machine_assignments a ON a.user_id=r.user_id WHERE r.user_id=auth.uid() AND r.role='machine_operator' AND r.plant_owner_id=p_owner AND a.machine_id=p_id) $$;
CREATE POLICY assignment_read ON public.machine_assignments FOR SELECT TO authenticated USING (user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.machines m WHERE m.id=machine_id AND public.is_plant_manager(m.owner_id)));
CREATE POLICY manager_invites ON public.operator_invites FOR SELECT TO authenticated USING (public.is_plant_manager(owner_id));
ALTER TABLE public.paper_records ADD COLUMN machine_id uuid REFERENCES public.machines(id);
DROP POLICY "own machines" ON public.machines;
CREATE POLICY machine_read ON public.machines FOR SELECT TO authenticated USING (public.can_read_machine(id,owner_id));
CREATE POLICY manager_machine_write ON public.machines FOR ALL TO authenticated USING(public.is_plant_manager(owner_id)) WITH CHECK(public.is_plant_manager(owner_id));
DROP POLICY "own events" ON public.maintenance_events;
CREATE POLICY event_read ON public.maintenance_events FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.machines m WHERE m.id=machine_id AND m.owner_id=maintenance_events.owner_id AND public.can_read_machine(m.id,m.owner_id)));
CREATE POLICY manager_event_write ON public.maintenance_events FOR ALL TO authenticated USING(public.is_plant_manager(owner_id)) WITH CHECK(public.is_plant_manager(owner_id) AND EXISTS(SELECT 1 FROM public.machines m WHERE m.id=machine_id AND m.owner_id=maintenance_events.owner_id));
DROP POLICY "own records" ON public.paper_records;
CREATE POLICY record_read ON public.paper_records FOR SELECT TO authenticated USING(public.is_plant_manager(owner_id) OR (machine_id IS NOT NULL AND public.can_read_machine(machine_id,owner_id)));
CREATE POLICY manager_record_write ON public.paper_records FOR ALL TO authenticated USING(public.is_plant_manager(owner_id)) WITH CHECK(public.is_plant_manager(owner_id));
CREATE POLICY operator_record_insert ON public.paper_records FOR INSERT TO authenticated WITH CHECK(machine_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.machines m WHERE m.id=machine_id AND m.owner_id=paper_records.owner_id AND m.line=paper_records.line AND public.can_read_machine(m.id,m.owner_id)));
CREATE FUNCTION public.assign_initial_plant_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.user_roles VALUES(NEW.id,'production_manager',NEW.id); RETURN NEW; END $$;
CREATE TRIGGER assign_initial_plant_role AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_initial_plant_role();
CREATE FUNCTION public.create_operator_invite(p_email text,p_machines uuid[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_owner uuid; v_token uuid; BEGIN SELECT plant_owner_id INTO v_owner FROM public.user_roles WHERE user_id=auth.uid() AND role='production_manager'; IF v_owner IS NULL THEN RAISE EXCEPTION 'Only production managers can invite operators'; END IF; IF cardinality(p_machines)<1 OR p_machines IS NULL OR EXISTS(SELECT 1 FROM unnest(p_machines) x WHERE NOT EXISTS(SELECT 1 FROM public.machines m WHERE m.id=x AND m.owner_id=v_owner)) THEN RAISE EXCEPTION 'Select machines from your plant'; END IF; IF p_email !~ '^[^@ ]+@[^@ ]+\.[^@ ]+$' THEN RAISE EXCEPTION 'Enter a valid email'; END IF; INSERT INTO public.operator_invites(owner_id,email,machine_ids) VALUES(v_owner,lower(trim(p_email)),p_machines) RETURNING token INTO v_token; RETURN v_token; END $$;
CREATE FUNCTION public.accept_operator_invite(p_token uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.operator_invites; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT * INTO v FROM public.operator_invites WHERE token=p_token AND accepted_by IS NULL AND expires_at>now() FOR UPDATE; IF v.id IS NULL OR lower(auth.jwt()->>'email') IS DISTINCT FROM v.email THEN RAISE EXCEPTION 'Invitation is expired or belongs to another email'; END IF; IF v.owner_id=auth.uid() THEN RAISE EXCEPTION 'You cannot join your own plant as an operator'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='machine_operator') THEN RAISE EXCEPTION 'This account already belongs to a plant'; END IF; IF EXISTS(SELECT 1 FROM public.operator_invites WHERE owner_id=auth.uid() AND accepted_by IS NOT NULL) THEN RAISE EXCEPTION 'A manager with active operators cannot switch plants'; END IF; UPDATE public.user_roles SET role='machine_operator',plant_owner_id=v.owner_id WHERE user_id=auth.uid(); INSERT INTO public.machine_assignments SELECT auth.uid(),x FROM unnest(v.machine_ids) x; UPDATE public.operator_invites SET accepted_by=auth.uid() WHERE id=v.id; END $$;
CREATE FUNCTION public.set_machine_status(p_machine uuid,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_status NOT IN ('running','idle','down') THEN RAISE EXCEPTION 'Invalid status'; END IF; UPDATE public.machines SET status=p_status WHERE id=p_machine AND public.can_read_machine(id,owner_id); IF NOT FOUND THEN RAISE EXCEPTION 'Machine is not assigned to you'; END IF; END $$;
REVOKE ALL ON FUNCTION public.create_operator_invite(text,uuid[]),public.accept_operator_invite(uuid),public.set_machine_status(uuid,text),public.is_plant_manager(uuid),public.can_read_machine(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_operator_invite(text,uuid[]),public.accept_operator_invite(uuid),public.set_machine_status(uuid,text),public.is_plant_manager(uuid),public.can_read_machine(uuid,uuid) TO authenticated;